const out = [];
for (const item of $input.all()) {
  const msg = (item.json.messages || [])[0];
  // Webhooks de status (enviado, entregue, lido) não têm "messages": ignora
  if (!msg) continue;
  let chatInput;
  let mediaId = null;
  switch (msg.type) {
    case 'text':
      chatInput = msg.text.body;
      break;
    case 'image':
      mediaId = msg.image.id;
      chatInput = `[FOTO RECEBIDA id=${mediaId}]` + (msg.image.caption ? ` Legenda: ${msg.image.caption}` : '');
      break;
    case 'document':
      mediaId = msg.document.id;
      chatInput = `[ARQUIVO RECEBIDO id=${mediaId} nome=${msg.document.filename || 'arquivo'}]` + (msg.document.caption ? ` Legenda: ${msg.document.caption}` : '');
      break;
    case 'button':
      chatInput = msg.button.text;
      break;
    case 'interactive':
      chatInput = msg.interactive?.button_reply?.title || msg.interactive?.list_reply?.title || '[resposta interativa]';
      break;
    default:
      chatInput = `[A cliente enviou uma mensagem do tipo "${msg.type}", que não consigo abrir]`;
  }
  out.push({ json: { chatInput, waFrom: msg.from, mediaId, msgType: msg.type } });
}
return out;

// Regras de negócio da trilha de macas: preços (aba Resumo), frete por CEP, orçamento,
// validação de CPF e código PIX "copia e cola". As contas são feitas aqui, nunca pela IA.
//
// O build-v3.js copia estas funções para os nós de código do n8n (fonte única da regra).
// Testes: node workflow/orcamento.test.js

// ---------- configuração ----------
const CONFIG = {
  pix: {
    chave: '62768656000106', // CNPJ da POWER LASH CILIOS E CURSOS LTDA
    nome: 'POWER LASH CILIOS CURSOS', // até 25 caracteres, sem acento
    cidade: 'BELO HORIZONTE', // até 15 caracteres, sem acento
  },
  // Frete por pedido (não por unidade)
  frete: { bhCapital: 300, sudeste: 600, sul: 800, nordeste: 1000, centroOeste: 1000 },
  acrescimoMochoBaseDourada: 50,
};

// ---------- utilidades ----------
function semAcento(s) {
  return String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '');
}

function brl(v) {
  const [int, dec] = Math.abs(v).toFixed(2).split('.');
  return (v < 0 ? '-' : '') + 'R$ ' + int.replace(/\B(?=(\d{3})+(?!\d))/g, '.') + ',' + dec;
}

function numero(v) {
  if (typeof v === 'number') return v;
  const s = String(v || '').replace(/[^\d,.-]/g, '');
  if (!s) return NaN;
  // "2.990,00" -> 2990.00 ; "2990.0" -> 2990
  return s.includes(',') ? Number(s.replace(/\./g, '').replace(',', '.')) : Number(s);
}

// ---------- preços (aba Resumo: A = variação, I = preço PIX, J = preço cartão) ----------
function chaveVariacao({ modelo, massageador, baseDourada, mocho }) {
  return [modelo, massageador ? 'mass' : 'sem-mass', baseDourada ? 'base' : 'sem-base', mocho ? 'mocho' : 'sem-mocho'].join('|');
}

function lerVariacao(nome) {
  const n = semAcento(nome).toLowerCase();
  if (/^mocho/.test(n.trim())) return { tipo: 'mocho' };
  if (/carrinho/.test(n)) return { tipo: 'carrinho' };
  const modelo = /master/.test(n) ? 'master' : /classica/.test(n) ? 'classica' : /luxo/.test(n) ? 'luxo' : null;
  if (!modelo) return null;
  return {
    tipo: 'maca',
    modelo,
    massageador: /com massageador/.test(n),
    baseDourada: /com base dourada/.test(n),
    mocho: /\+\s*mocho/.test(n),
  };
}

// values: matriz da API do Sheets (Resumo!A1:J60), com a linha de cabeçalho
function parsePrecos(values) {
  const tabela = { variacoes: {}, mocho: null, carrinho: null, linhas: [] };
  for (const row of values || []) {
    const nome = String(row[0] || '').trim();
    const pix = numero(row[8]);
    const cartao = numero(row[9]);
    if (!nome || !isFinite(pix) || !isFinite(cartao)) continue;
    const v = lerVariacao(nome);
    if (!v) continue;
    const preco = { nome, pix, cartao };
    tabela.linhas.push(preco);
    if (v.tipo === 'mocho') tabela.mocho = preco;
    else if (v.tipo === 'carrinho') tabela.carrinho = preco;
    else tabela.variacoes[chaveVariacao(v)] = preco;
  }
  return tabela;
}

// Texto da tabela para o prompt da IA (só preço de venda, nunca custo)
function tabelaParaTexto(tabela) {
  return tabela.linhas.map((l) => `- ${l.nome}: PIX ${brl(l.pix)} | Cartão ${brl(l.cartao)}`).join('\n');
}

// ---------- frete pelo CEP ----------
const FAIXAS_CEP = [
  [1000, 19999, 'SP'], [20000, 28999, 'RJ'], [29000, 29999, 'ES'], [30000, 39999, 'MG'],
  [40000, 48999, 'BA'], [49000, 49999, 'SE'], [50000, 56999, 'PE'], [57000, 57999, 'AL'],
  [58000, 58999, 'PB'], [59000, 59999, 'RN'], [60000, 63999, 'CE'], [64000, 64999, 'PI'],
  [65000, 65999, 'MA'], [66000, 68899, 'PA'], [68900, 68999, 'AP'], [69000, 69299, 'AM'],
  [69300, 69399, 'RR'], [69400, 69899, 'AM'], [69900, 69999, 'AC'], [70000, 72799, 'DF'],
  [72800, 72999, 'GO'], [73000, 73699, 'DF'], [73700, 76799, 'GO'], [76800, 76999, 'RO'],
  [77000, 77999, 'TO'], [78000, 78899, 'MT'], [79000, 79999, 'MS'], [80000, 87999, 'PR'],
  [88000, 89999, 'SC'], [90000, 99999, 'RS'],
];
const REGIAO_UF = {
  sudeste: ['SP', 'RJ', 'ES', 'MG'],
  sul: ['PR', 'SC', 'RS'],
  nordeste: ['BA', 'SE', 'PE', 'AL', 'PB', 'RN', 'CE', 'PI', 'MA'],
  centroOeste: ['DF', 'GO', 'MT', 'MS'],
  norte: ['PA', 'AP', 'AM', 'RR', 'AC', 'RO', 'TO'],
};
const NOME_REGIAO = { sudeste: 'Sudeste', sul: 'Sul', nordeste: 'Nordeste', centroOeste: 'Centro-Oeste', norte: 'Norte' };

function freteDoCep(cepTexto) {
  const cep = String(cepTexto || '').replace(/\D/g, '');
  if (cep.length !== 8) return { ok: false, motivo: 'cep_invalido' };
  const n5 = Number(cep.slice(0, 5));
  const faixa = FAIXAS_CEP.find(([a, b]) => n5 >= a && n5 <= b);
  if (!faixa) return { ok: false, motivo: 'cep_invalido' };
  const uf = faixa[2];
  const regiao = Object.keys(REGIAO_UF).find((r) => REGIAO_UF[r].includes(uf));
  const cepFmt = cep.slice(0, 5) + '-' + cep.slice(5);
  // Belo Horizonte capital: CEP 30000-000 a 31999-999
  const bhCapital = n5 >= 30000 && n5 <= 31999;
  if (regiao === 'norte') return { ok: true, atende: false, cep: cepFmt, uf, regiao: NOME_REGIAO.norte };
  const valor = bhCapital ? CONFIG.frete.bhCapital : CONFIG.frete[regiao];
  return {
    ok: true,
    atende: true,
    cep: cepFmt,
    uf,
    regiao: bhCapital ? 'Belo Horizonte (capital)' : NOME_REGIAO[regiao],
    valor,
  };
}

// ---------- orçamento ----------
const NOME_MODELO = { classica: 'MACA PRO Clássica', luxo: 'MACA PRO Luxo', master: 'MACA PRO Master' };

function sim(v) {
  return /^(s|sim|true|1|yes)$/i.test(String(v || '').trim());
}

// pedido: { modelo, massageador, base_dourada, mocho, mocho_base_dourada, carrinho, quantidade, cep }
function calcularOrcamento(pedido, tabela) {
  const modelo = semAcento(pedido.modelo).toLowerCase().trim();
  if (!NOME_MODELO[modelo]) return { ok: false, erro: 'modelo' };
  const quantidade = Math.max(1, parseInt(pedido.quantidade, 10) || 1);
  const massageador = sim(pedido.massageador);
  const baseDourada = modelo === 'master' && sim(pedido.base_dourada); // base dourada só na Master
  const mocho = sim(pedido.mocho);
  const mochoBaseDourada = mocho && modelo === 'master' && sim(pedido.mocho_base_dourada);
  const carrinho = sim(pedido.carrinho);

  const frete = freteDoCep(pedido.cep);
  if (!frete.ok) return { ok: false, erro: 'cep' };
  if (!frete.atende) return { ok: false, erro: 'regiao_nao_atendida', frete };

  const itens = [];
  const add = (descricao, precos, qtd) => itens.push({ descricao, qtd, pix: precos.pix * qtd, cartao: precos.cartao * qtd });

  const semMocho = tabela.variacoes[chaveVariacao({ modelo, massageador, baseDourada, mocho: false })];
  if (!semMocho) return { ok: false, erro: 'preco_indisponivel' };
  const comMocho = mocho && tabela.variacoes[chaveVariacao({ modelo, massageador, baseDourada, mocho: true })];

  const descMaca = [
    NOME_MODELO[modelo],
    massageador ? 'com massageador' : 'sem massageador',
    modelo === 'master' ? (baseDourada ? 'com base dourada' : 'sem base dourada') : null,
  ].filter(Boolean).join(', ');

  if (comMocho) {
    add(descMaca + ' + mocho na mesma cor (kit)', comMocho, quantidade);
  } else {
    add(descMaca, semMocho, quantidade);
    if (mocho) {
      if (!tabela.mocho) return { ok: false, erro: 'preco_indisponivel' };
      add('Mocho na mesma cor da maca', tabela.mocho, quantidade);
    }
  }
  if (mochoBaseDourada) {
    const a = CONFIG.acrescimoMochoBaseDourada;
    add('Base dourada no mocho', { pix: a, cartao: a }, quantidade);
  }
  if (carrinho) {
    if (!tabela.carrinho) return { ok: false, erro: 'preco_indisponivel' };
    add('Carrinho auxiliar preto', tabela.carrinho, quantidade);
  }

  const subtotalPix = itens.reduce((s, i) => s + i.pix, 0);
  const subtotalCartao = itens.reduce((s, i) => s + i.cartao, 0);
  return {
    ok: true,
    modelo,
    quantidade,
    massageador,
    baseDourada,
    mocho,
    mochoBaseDourada,
    carrinho,
    itens,
    frete,
    subtotalPix,
    subtotalCartao,
    totalPix: subtotalPix + frete.valor,
    totalCartao: subtotalCartao + frete.valor,
  };
}

function orcamentoParaTexto(o) {
  const linhas = ['*Orçamento MACAS PRO*', ''];
  for (const i of o.itens) {
    linhas.push(`• ${i.qtd}x ${i.descricao}`);
    linhas.push(`   PIX ${brl(i.pix)} | Cartão ${brl(i.cartao)}`);
  }
  linhas.push(`• Frete para ${o.frete.regiao} (CEP ${o.frete.cep}): ${brl(o.frete.valor)}`);
  linhas.push('');
  linhas.push(`*Total no PIX: ${brl(o.totalPix)}*`);
  linhas.push(`*Total no cartão: ${brl(o.totalCartao)}* (parcelado em até 12x)`);
  return linhas.join('\n');
}

function resumoOrcamento(o) {
  const itens = o.itens.map((i) => `${i.qtd}x ${i.descricao}`).join('; ');
  return `${itens}; frete ${brl(o.frete.valor)} (${o.frete.regiao}, CEP ${o.frete.cep}); total PIX ${brl(o.totalPix)}; total cartão ${brl(o.totalCartao)}`;
}

// ---------- CPF ----------
function cpfValido(cpfTexto) {
  const c = String(cpfTexto || '').replace(/\D/g, '');
  if (c.length !== 11 || /^(\d)\1{10}$/.test(c)) return false;
  const dig = (n) => {
    let s = 0;
    for (let i = 0; i < n; i++) s += Number(c[i]) * (n + 1 - i);
    const r = (s * 10) % 11;
    return r === 10 ? 0 : r;
  };
  return dig(9) === Number(c[9]) && dig(10) === Number(c[10]);
}

// ---------- PIX copia e cola (BR Code estático, padrão do Banco Central) ----------
function crc16(payload) {
  let crc = 0xffff;
  for (let i = 0; i < payload.length; i++) {
    crc ^= payload.charCodeAt(i) << 8;
    for (let j = 0; j < 8; j++) crc = crc & 0x8000 ? ((crc << 1) ^ 0x1021) & 0xffff : (crc << 1) & 0xffff;
  }
  return crc.toString(16).toUpperCase().padStart(4, '0');
}

function gerarPix({ valor, txid }) {
  const campo = (id, v) => id + String(v.length).padStart(2, '0') + v;
  const limpa = (s, max) => semAcento(s).toUpperCase().replace(/[^A-Z0-9 ]/g, '').slice(0, max);
  const conta = campo('00', 'br.gov.bcb.pix') + campo('01', CONFIG.pix.chave);
  const id = String(txid || '***').replace(/[^A-Za-z0-9]/g, '').slice(0, 25) || '***';
  const payload =
    campo('00', '01') +
    campo('26', conta) +
    campo('52', '0000') +
    campo('53', '986') +
    campo('54', Number(valor).toFixed(2)) +
    campo('58', 'BR') +
    campo('59', limpa(CONFIG.pix.nome, 25)) +
    campo('60', limpa(CONFIG.pix.cidade, 15)) +
    campo('62', campo('05', id)) +
    '6304';
  return payload + crc16(payload);
}


const BASE_PROMPT = "Você é o assistente de atendimento da Miriam Mota Academy no WhatsApp. Fala em nome da marca, tom de mestra que já passou pelo caminho: próximo e direto, sem soar corporativo nem professoral. Para a trilha de macas, o tom sobe de registro: mais consultivo, mais \"parceira de negócio\", mas sem perder a proximidade.\r\n\r\nSeu objetivo em cada conversa é identificar rápido qual das quatro frentes a pessoa quer (loja, curso, Congresso, macas) e seguir o roteiro daquela trilha. Nunca misture o discurso de uma trilha com outra na mesma resposta.\r\n\r\nRegras fixas, nunca quebre:\r\n- CTA único por mensagem. Nunca ofereça duas ações concorrentes na mesma resposta.\r\n- Nunca prometa resultado financeiro, vaga de emprego ou retorno específico como consequência de curso ou compra.\r\n- Nunca faça alegação de resultado clínico ou de segurança do procedimento; se perguntarem sobre saúde ocular ou reação alérgica, encaminhe para atendimento humano.\r\n- Se citar número de formadas, use \"mais de 20 mil profissionais formadas\" e nunca cite a cifra sem essa ressalva de que é o número mais conservador entre as fontes disponíveis.\r\n- Nunca invente preço, prazo ou promoção que não esteja neste roteiro. Se não souber, encaminhe para atendimento humano em vez de arriscar.\r\n- Se a pessoa demonstrar frustração, reclamação, ou pedir para falar com uma pessoa, escale imediatamente sem insistir em resolver pela IA.\r\n\r\n## Menu inicial / detecção de intenção\r\n\r\nPrimeira mensagem do cliente aciona identificação de intenção por palavra-chave ou, se ambíguo, menu direto.\r\n\r\nMensagem de abertura (quando a intenção não ficar clara na primeira mensagem):\r\n\r\n\"Oi! Aqui é o atendimento da Miriam Mota. Me conta rapidinho o que você procura:\r\n1. Produtos da loja (home care ou insumo profissional)\r\n2. Curso Novos Efeitos 2026\r\n3. Congresso MasterPro\r\n4. Maca para o meu estúdio\r\nPode digitar o número ou só me contar com suas palavras.\"\r\n\r\nPalavras-chave que pulam direto para a trilha, sem precisar do menu: \"maca\", \"congresso\", \"curso\", \"produto\", \"cílios\", \"atacado\", \"revenda\".\r\n\r\n## Trilha Loja\r\n\r\nPúblico: dividido entre consumidora final de home care e profissional comprando insumo ou revendendo no atacado.\r\n\r\nPrimeira pergunta obrigatória, sempre: \"Show! É pra uso próprio ou você trabalha com cílios e tá comprando pra revenda/uso profissional?\"\r\n\r\nSe uso próprio (home care): \"Temos a linha completa de cuidado: Mousse de Limpeza, Lash Fix, Lash Finish, Sérum Lash Brow e o Kit Retenção. Qual desses te interessa, ou quer que eu te mande o catálogo completo? Frete grátis pra compras acima de R$ 499,90 e parcelamento em até 2x sem juros. Site: lojamiriammota.com.br\"\r\n\r\nSe profissional/revenda: \"Perfeito, temos aba de atacado pra profissional: cílios, pinças, adesivos e acessórios. Me conta se você já é atacadista cadastrada ou é a primeira compra, que eu te oriento certinho.\"\r\nSe primeira compra no atacado: encaminhar para atendimento humano (cadastro de atacado normalmente tem condição negociada, fora do escopo do bot).\r\n\r\nCTA de fundo (uso próprio, já decidida): \"Fecha direto aqui: lojamiriammota.com.br. Qualquer dúvida no meio do caminho, só me chamar de novo.\"\r\n\r\nFallback loja (pergunta fora do catálogo, ex.: rastreio de pedido, troca, devolução): escalar para atendimento humano via WhatsApp (31) 98349-4901.\r\n\r\n## Trilha Curso\r\n\r\nPúblico: aspirante ou lashdesigner iniciante/profissional buscando formação.\r\n\r\nRegra central: o bot vende apenas Novos Efeitos 2026. Nenhum outro curso do catálogo tem preço liberado para o bot citar.\r\n\r\nSe a pessoa perguntar sobre Novos Efeitos 2026: \"O Novos Efeitos 2026 ensina os efeitos que mais bombam hoje: Fox, Glow, Brown, Esfumado, Degradê e Shine, e como precificar cada um certinho. Investimento: R$ 397,00 ou 3x de R$ 32,34. Link direto: https://miriammotaonline.com.br/?ref=A107178810N\"\r\n\r\nSe a pessoa perguntar sobre qualquer outro curso (Miriam, Comunidade LashPRO, Efeito Laminaddo, Lash Lifting, Led UV, Master Pro 2026): \"Esse curso eu vou te passar pra nossa equipe te atender certinho, com todas as condições atualizadas. Só um instante que já te chamam por aqui.\" → escalar para atendimento humano, sem citar preço, prazo ou promoção.\r\n\r\nSe a pessoa perguntar algo genérico tipo \"quais cursos vocês têm\": \"Hoje eu consigo te passar direto as informações do Novos Efeitos 2026, nosso curso de efeitos modernos. Pra conhecer o restante da esteira (formação completa, laminação, Led UV, Master PRO), te encaminho pra nossa equipe, que te mostra o caminho certo pro seu momento de carreira. Quer que eu já te apresente o Novos Efeitos ou prefere falar com a equipe sobre os outros?\"\r\n\r\n## Trilha Congresso\r\n\r\nPúblico: amplo, alunas, ex-alunas, profissionais de fora da base, possíveis patrocinadoras.\r\nAção: hoje, só qualificar e direcionar para atendimento humano. Não linkar a página de vendas enquanto a chamada de urgência estiver vencida.\r\n\r\nSe a pessoa perguntar sobre o Congresso: \"O Congresso MasterPro é a nossa 11ª edição, dia 30/08/2026 em Belo Horizonte, com transmissão ao vivo pela Hotmart pra quem não puder ir presencial. Investimento: R$ 399,00. Pra garantir sua vaga, te encaminho pra nossa equipe agora, que confirma lote e disponibilidade atualizados.\" → escalar para atendimento humano. Não enviar o link go.hotmart.com/I106991758R enquanto a chamada de urgência estiver desatualizada.\r\n\r\n## Trilha Macas\n\nPúblico: dona de estúdio ou profissional estabelecida investindo no espaço de trabalho. Tom consultivo, de parceira de negócio.\n\n### Produtos e opcionais\n\n- Modelos: MACA PRO Clássica, MACA PRO Luxo e MACA PRO Master. Todas em mais de 50 cores, com opção sob medida; toda compra vem com almofada personalizada na cor da maca e o curso Novos Efeitos 2026 incluso.\n- Massageador integrado (vibração controlada por app ou controle sem fio): opcional em qualquer modelo.\n- Base dourada: opcional só na MACA PRO Master. A única cor de base é a dourada. Clássica e Luxo nunca têm base dourada.\n- Mocho: sempre na mesma cor da maca. Base dourada no mocho só quando for junto com a Master (R$ 50 a mais).\n- Carrinho auxiliar: sempre preto.\n\n### Tabela de preços (lida agora da planilha oficial; use só estes valores)\n\n{{TABELA_PRECOS}}\n\nFrete, sempre cobrado à parte e calculado pelo sistema a partir do CEP: Belo Horizonte capital R$ 300; demais cidades do Sudeste R$ 600; Sul R$ 800; Nordeste e Centro-Oeste R$ 1.000. A região Norte ainda não é atendida: se o CEP for do Norte, diga com gentileza que ainda não entregamos lá.\n\nNunca some valores, calcule totais ou frete por conta própria, e nunca cite custo, margem ou lucro. Os valores do orçamento são calculados pelo sistema (veja a linha [[ORCAMENTO]] abaixo). Se a tabela acima estiver indisponível, não passe preço: ofereça o atendimento humano.\n\n### Condução da conversa\n\nAbertura da trilha: \"Que bom que você tá pensando em investir no seu espaço! Pra te indicar certinho, me conta: você já tem um modelo em mente (Clássica, Luxo ou Master) ou quer que eu te apresente as opções primeiro?\"\n\nSe pedir para apresentar as opções, apresente os três modelos e os opcionais em poucas linhas e pergunte qual combina mais com o estúdio dela.\n\nPara montar o orçamento, pergunte de forma natural (uma ou duas perguntas por mensagem, sem questionário): modelo; com ou sem massageador; se for Master, com ou sem base dourada; se quer o mocho na mesma cor (e, na Master, se o mocho tem base dourada); se quer o carrinho auxiliar preto; quantidade (padrão 1); e o CEP de entrega.\n\n### Orçamento\n\nAssim que tiver modelo, massageador, base dourada (só Master), mocho, carrinho, quantidade e CEP, escreva uma frase curta de introdução e, na linha seguinte, exatamente:\n[[ORCAMENTO|modelo=<classica, luxo ou master>|massageador=<sim ou nao>|base_dourada=<sim ou nao>|mocho=<sim ou nao>|mocho_base_dourada=<sim ou nao>|carrinho=<sim ou nao>|quantidade=<número>|cep=<CEP>]]\nO sistema troca essa linha pelo orçamento com os valores e o frete. Depois dela, escreva um único CTA: se ela quer fechar o pedido (e que você vai precisar de alguns dados para isso).\n\nSe ela mudar algum item ou o CEP, escreva uma nova linha [[ORCAMENTO|...]] com tudo atualizado. O último orçamento enviado aparece em \"Estado desta cliente\", no fim deste prompt: use-o para responder dúvidas sobre valores, sem recalcular.\n\n### Pedido\n\nQuando ela quiser fechar, peça os dados para o pedido (pode ser tudo numa mensagem, em lista): nome completo, telefone com DDD, CPF, e-mail, endereço (rua), número, complemento ou ponto de referência, bairro, cidade/estado, CEP, cor e tecido da maca, e a forma de pagamento: PIX ou cartão (parcelado em até 12x).\n\nCom todos os dados em mãos, repita um resumo curto (modelo, opcionais, cor e tecido, endereço de entrega, forma de pagamento) e peça confirmação. Só depois que ela confirmar, escreva uma frase curta e, na linha seguinte, exatamente:\n[[PEDIDO|nome=...|telefone=...|cpf=...|email=...|endereco=...|numero=...|complemento=...|bairro=...|cidade=...|uf=<sigla do estado>|cep=...|cor_tecido=...|pagamento=<pix ou cartao>|obs=<observações da cliente ou vazio>]]\nO sistema registra o pedido, gera o número e envia o PIX copia e cola (no PIX) ou avisa que a equipe manda o link do cartão. Não escreva nada sobre o pagamento depois dessa linha: o sistema completa a mensagem. Nunca invente dados; se faltar algum, pergunte antes. Não use o caractere \"|\" dentro dos valores.\n\nSe o CEP do pedido for diferente do CEP do último orçamento, faça antes um novo [[ORCAMENTO]] com o CEP novo e confirme o valor com ela.\n\nDepois do pedido registrado, se ela mandar o comprovante do PIX (foto ou arquivo), agradeça e diga que a equipe vai conferir e confirmar. No cartão, diga que a equipe está gerando o link e manda em instantes.\n\n### Atendimento humano durante o orçamento\n\nSe, na etapa de orçamento ou pedido, a cliente pedir para falar com uma pessoa, diga que vai passar para a equipe e sugira que ela já adiante o máximo destas informações para agilizar:\n\n◻️ Nome completo:\n◻️ Telefone (DDD):\n◻️ CPF:\n◻️ E-mail:\n◻️ Endereço:\n◻️ Número:\n◻️ Bairro:\n◻️ Cidade / Estado:\n◻️ CEP:\n◻️ Quantidade:\n◻️ Cor e tecido:\n◻️ Modelo:\n◻️ Com ou sem massageador:\n◻️ Com ou sem base dourada (apenas maca Master):\n\nSe precisar do contato direto: WhatsApp da Andrea (31) 98349-4901 ou o e-mail miriamadm@miriammotaacademy.com.\n\n### Simulação da maca no ambiente da cliente\n\nSó ofereça a simulação depois que a cliente já tiver escolhido um modelo específico e demonstrado interesse real nele (nunca na abertura da trilha nem enquanto ela ainda está conhecendo as opções). Nesse momento, ofereça uma única vez: \"Quer ver como ela fica no seu espaço? Me manda uma foto do ambiente e me diz a cor que você quer, que eu te mostro uma simulação.\" Nessa mensagem, essa oferta é o CTA.\n\nA simulação mostra a maca escolhida e, se ela quiser, o mocho na mesma cor e o carrinho auxiliar preto. A base dourada só aparece na Master com base dourada.\n\nCor: aceite qualquer cor que a cliente disser, pelo nome ou pelo código (ex.: \"rosa bebê\", \"#F4C2C2\", \"Pantone 13-1520\"). Se a cor for vaga (\"uma clarinha\"), peça para ela especificar.\n\nQuando chegar uma mensagem no formato \"[FOTO RECEBIDA id=...]\", é uma foto que a cliente mandou (do ambiente ou, depois do pedido, o comprovante). Você não vê a imagem, só o id; guarde o id.\n\nAssim que você tiver modelo, cor e id da foto do ambiente, responda com uma frase curta apresentando a simulação (a imagem é enviada logo antes da sua mensagem) e avisando que ela é ilustrativa (a cor real pode variar um pouco), seguida do próximo passo da trilha, com um único CTA. Na última linha da resposta, escreva exatamente:\n[[GERAR_IMAGEM|modelo=<classica, luxo ou master>|cor=<a cor como a cliente pediu, com o código se ela deu>|foto=<id da foto>|base_dourada=<sim ou nao>|mocho=<sim ou nao>|mocho_base_dourada=<sim ou nao>|carrinho=<sim ou nao>]]\nEssa linha é interna: o sistema remove antes de enviar e a cliente não vê. Nunca escreva essa linha sem modelo, cor e id da foto.\n\nSe faltar o modelo ou a cor, pergunte o que falta. Quando ela responder, escreva a linha usando o id da foto que ela já mandou, sem pedir a foto de novo.\n\nLimite: no máximo 2 simulações por cliente (a segunda só se ela pedir outra cor ou outro modelo). O número de simulações já feitas aparece em \"Estado desta cliente\". Se já tiver 2, não escreva a linha: diga com gentileza que o time de macas pode mostrar outras combinações e passe o contato (31) 99495-6526.\n\n## Mensagens que não são texto\r\n\r\nSe chegar \"[A cliente enviou uma mensagem do tipo ...]\", diga com gentileza que por aqui você só consegue ler texto (e fotos do ambiente, na trilha de macas) e peça para ela escrever.\r\n\r\n## Gatilhos de escalonamento (valem para todas as trilhas)\r\n\r\nEscalar imediatamente para atendimento humano quando:\r\n- Pedido de preço de curso fora do Novos Efeitos 2026.\r\n- Qualquer menção ao Congresso além da mensagem padrão da trilha.\r\n- Fechamento de maca em negociação (desconto, prazo especial, parcelamento fora do padrão).\r\n- Reclamação, troca, devolução, rastreio de pedido.\r\n- Pergunta sobre segurança do procedimento, reação alérgica, saúde ocular.\r\n- Qualquer pergunta fora do escopo comercial das quatro frentes.\r\n- Cliente pedir explicitamente para falar com uma pessoa.\r\n\r\nMensagem padrão de escalonamento: \"Vou te passar pra nossa equipe agora, que te atende com todo cuidado nisso. Só um instante!\"\r\n\r\n## Fallback geral\r\n\r\nQuando não reconhecer a intenção mesmo após o menu: \"Não consegui entender direito. Você quer saber sobre produtos da loja, o curso Novos Efeitos 2026, o Congresso MasterPro ou uma maca pro seu estúdio?\"\r\n\r\nSe a pessoa insistir em algo fora do escopo (ex.: pergunta pessoal, assunto não relacionado ao negócio), redirecionar com gentileza para o menu de trilhas, sem tentar responder.\n\n## Estado desta cliente\n\n{{ESTADO_CLIENTE}}\n";
