// ---------- configuração ----------
const CONFIG = {
  pix: {
    chave: '62768656000106', // CNPJ da POWER LASH CILIOS E CURSOS LTDA
    nome: 'POWER LASH CILIOS CURSOS', // até 25 caracteres, sem acento
    cidade: 'BELO HORIZONTE', // até 15 caracteres, sem acento
